// ai-agents/orchestrator/src/triggers/schedules.ts (part 2): at worker start; safe to run twice
export const ensureSchedules = async (client: Client): Promise<void> => {
  for (const q of QUERIES.values()) {
    const scheduleId = `poll-jira-${q.name}`;
    const action = { type: "startWorkflow" as const, workflowType: pollJira, args: [q.name],
      workflowId: scheduleId, taskQueue: "ai-agents-orchestrator" };
    const spec = { intervals: [{ every: q.every }] };
    const policies = { overlap: ScheduleOverlapPolicy.SKIP, catchupWindow: q.every }; // an outage doesn't replay a backlog
    await client.schedule.create({ scheduleId, action, spec, policies }).catch(async (err: unknown) => {
      if (!(err instanceof ScheduleAlreadyRunning)) throw err;
      await client.schedule.getHandle(scheduleId).update((prev) => ({ ...prev, action, spec, policies }));
    });
  }
};

// ai-agents/orchestrator/src/triggers/schedules.ts (part 1): one mechanism for every Jira trigger
export interface JiraQuery {
  name: string; agent: string; jql: string; every: string;
  toStart: (issue: JiraIssue) => Promise<[Workflow, unknown] | undefined>; // workflow + input, or skip
}
export const QUERIES = new Map<string, JiraQuery>();

/** Activity: one poll of one query. startRun refuses a stopped agent (G3-25). */
export const startMatches = async (name: string): Promise<number> => {
  const q = QUERIES.get(name)!;
  const issues = await jira.searchAll(q.jql);
  for (const issue of issues) {
    const start = await q.toStart(issue);
    if (!start) continue; // e.g. no requester found yet (G4-04)
    const [wf, input] = start;
    await startRun(await temporalClient(), q.agent, issue.key, wf, input); // the ID makes repeats no-ops
  }
  return issues.length;
};

// workflows/poll-jira.ts: workflow code; peopleApis = SHORT + PEOPLE_APIS retries (G3-29)
export async function pollJira(name: string): Promise<number> {
  return peopleApis.startMatches(name);
}

// ai-agents/orchestrator/src/triggers/nova.ts (part of G4-04): Nova's entry in the registry
// Runs as the Nova service account, so currentUser() is Nova.
const NOVA_JQL = "project = RH AND assignee = currentUser() AND statusCategory != Done ORDER BY updated ASC";

QUERIES.set("nova", {
  name: "nova", agent: "nova", jql: NOVA_JQL, every: "1 minute",
  toStart: async (issue) => {
    const requester = await requesterOf(issue.key); // who assigned it to Nova (p9-2)
    if (!requester) return undefined; // no owner found: log it, start nothing
    const handoff: Handoff = { key: issue.key, requester };
    return [ticketToPr, handoff]; // a second poll joins the open run
  },
});

// ai-agents/orchestrator/src/triggers/schedules.ts (G5-13's part): cron schedules for routines
const CRON: Record<string, [cron: string, workflow: Workflow, args: unknown[]]> = { // odd minutes; 0-4 = Sun-Thu
  "fe-dead-code": ["17 4 * * 0-4", routineRun, [{ routine: "fe-dead-code" }]],
  "kb-ingest": ["41 6 * * 1", routineRun, [{ routine: "kb-ingest" }]],
  "team-digest": ["37 6 * * 0-4", teamDigest, []],
};

export async function ensureCronSchedules(client: Client): Promise<void> {
  for (const [name, [cron, workflowType, args]] of Object.entries(CRON)) {
    const scheduleId = `sched:${name}`;
    const schedule = {
      spec: { cronExpressions: [cron], timezone: "Asia/Jerusalem" },
      action: { type: "startWorkflow" as const, workflowType, args, workflowId: scheduleId, taskQueue: queueFor(name) },
      policies: { overlap: ScheduleOverlapPolicy.SKIP }, // a slow run never stacks a second one
    };
    // create, or update when it exists: the same catch as ensureSchedules
  }
}

